def legend_assignments(game_id: int, user_ids: Sequence[int]) -> dict[int, PlayerLegend]:
    """Assign distinct legends per game, stable for that game and shuffled again next game."""
    ids = sorted(set(user_ids))
    if len(ids) > len(LEGENDS):
        raise ValueError("Not enough legends for players")

    seed = hashlib.sha256(f"legends:{game_id}".encode()).digest()[:8]
    rng = random.Random(int.from_bytes(seed, "big"))
    pool = list(LEGENDS)
    rng.shuffle(pool)
    return {user_id: pool[index] for index, user_id in enumerate(ids)}


def random_legend(*, rng: random.Random | None = None) -> PlayerLegend:
    """Return a random legend for the solo test preview."""
    return (rng or random.SystemRandom()).choice(LEGENDS)
